    /** from:"headers" 配 path 时首段头名大小写不敏感匹配（与断言 from:"headers"、header 简写同口径）；from:"response" 仍按精确键匹配 */
    from?: ExtractSource;
    /** 提取目标：status=HTTP 状态码（缺省按 body 取值） */
    target?: "status";
    /** 响应头名简写（与断言 header 同口径）；配合 path 可在头值上继续取子路径（如 length） */
